const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='sienna-bahamas-production-v1',STAGES=['Confirmation pending','Ready to film','Filmed','Editing','Review','Approved','Published'];
const ICONS={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',listings:'M3 10l9-7 9 7 M5 9v12h14V9 M9 21v-8h6v8',communities:'M2 21h20 M4 21V8h6v13 M14 21V3h6v18 M6 11h2 M6 15h2 M16 7h2 M16 11h2 M16 15h2',scripts:'M4 3h12l4 4v14H4z M8 11h8 M8 15h8 M8 7h4',routes:'M3 6l6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',faq:'M21 11a8 8 0 0 1-8 8H7l-5 3 2-7a8 8 0 1 1 17-4z M9 8a3 3 0 0 1 6 0c0 2-3 2-3 4 M12 15h.01',launch:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16 M8 14h2 M14 14h2',files:'M3 6h7l2 3h9v12H3z M3 6V3h7l2 3h7v3',settings:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M6 6l2 2 M16 16l2 2 M6 18l2-2 M16 8l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'M4 12l5 5L20 6',play:'M8 4l12 8-12 8z'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[n]||ICONS.scripts}"/></svg>`;
const NAV=[['overview','Overview',''],['listings','Listings','29'],['communities','Communities','12'],['scripts','Script library','115'],['routes','Shoot routes','12'],['faq','Buyer FAQ','18'],['launch','Launch queue','45'],['files','Documents','3'],['settings','Brand & settings','']];
let D,state={assets:{},properties:{},routeDates:{},notes:{},career:{},domain:''},view='overview',filters={query:'',island:'all',format:'all',stage:'all',page:1},selectedRoute='D05',modalId=null,lastFocus=null,teleTimer=null,saveFailed=false;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.version===1)state={...state,...saved.data}}catch{}
const safeUrl=u=>/^https:\/\//.test(u||'')?esc(u):'#';
const stage=id=>state.assets[id]?.status||STAGES[0],as=a=>state.assets[a]||{},prop=id=>state.properties[id]||{},subject=id=>D.listings.find(r=>r.id===id)?.name||D.communities.find(r=>r.id===id)?.name||(id==='FAQ'?'Buying in The Bahamas':'Nassau buyer guide');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,data:state,updatedAt:new Date().toISOString()}));saveFailed=false;return true}catch{saveFailed=true;toast('Progress could not save. Export a backup before closing.');$('.device-note').textContent='Progress not saved — export a backup';return false}}
function setAsset(id,key,value){state.assets[id]={...as(id),[key]:value,updatedAt:new Date().toISOString()};save()}
// General production notes stay separate from agent-confirmation records.
function noteKeyAllowed(key){const [scope,id,...rest]=key.split(':');if(rest.length)return false;return scope==='module'?NAV.some(n=>n[0]===id):scope==='property'?D.listings.some(r=>r.id===id):scope==='community'?D.communities.some(c=>c.id===id):scope==='route'?D.routes.some(r=>r.id===id):scope==='asset'?D.assets.some(a=>a.id===id):false}
function noteRecord(key){if(key.startsWith('asset:')){const record=as(key.slice(6));return {text:record.notes||'',updatedAt:record.updatedAt||''}}return state.notes?.[key]||{text:'',updatedAt:''}}
function writeNote(key,text){if(!noteKeyAllowed(key))return false;const updatedAt=new Date().toISOString(),value=String(text).slice(0,10000);if(key.startsWith('asset:')){const id=key.slice(6);state.assets[id]={...as(id),notes:value,updatedAt}}else{state.notes??={};state.notes[key]={text:value,updatedAt}}return save()}
function notesEditor(key,label,placeholder='Ideas, changes to make, questions and filming reminders…',expanded=false){const note=noteRecord(key),hasNote=Boolean(note.text.trim()),inputId='note-'+key.replace(':','-');return `<details class="note-editor" data-note-panel="${esc(key)}" ${expanded?'open':''}><summary><span class="note-icon" aria-hidden="true">✎</span><span class="note-title">${esc(label)}</span><span class="note-badge" data-note-label>${hasNote?'View / edit notes':'Add notes'}</span><span class="note-chevron" aria-hidden="true">+</span></summary><div class="note-body"><label class="mini-label" for="${inputId}">Your notes</label><textarea id="${inputId}" data-workspace-note="${esc(key)}" aria-label="${esc(label)}" maxlength="10000" placeholder="${esc(placeholder)}">${esc(note.text)}</textarea><div class="note-footer"><span class="note-save" data-note-save role="status" aria-live="polite">${saveFailed?'Not saved — export progress before closing':hasNote?'Saved on this browser':'Saves automatically as you type'}</span><span class="note-count" data-note-count>${note.text.length.toLocaleString()} / 10,000</span></div><p class="note-help">Included in Export progress. Notes are saved on this browser and are not shared with the team yet.</p></div></details>`}
function showNotes(key){const panel=$(`[data-note-panel="${key}"]`);if(!panel)return;panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'nearest'});panel.querySelector('textarea').focus()}
function updateNoteFeedback(el,ok){const panel=el.closest('.note-editor');if(!panel)return;panel.querySelector('[data-note-save]').textContent=ok?'Saved on this browser':'Not saved — export progress before closing';panel.querySelector('[data-note-save]').classList.toggle('note-error',!ok);panel.querySelector('[data-note-label]').textContent=el.value.trim()?'View / edit notes':'Add notes';panel.querySelector('[data-note-count]').textContent=el.value.length.toLocaleString()+' / 10,000'}
function getGroup(r){return ['ABACO','ELEUTHERA','EXUMA'].includes(r.community)?r.community:'NASSAU'}
const pill=(s,cls='')=>`<span class="pill ${cls}">${esc(s)}</span>`;
const statusPill=id=>pill(stage(id),stage(id)==='Confirmation pending'?'warning':stage(id)==='Published'?'navy':'');
function head(title,sub,extra=''){return `<div class="page-head"><div><div class="eyebrow">THE BAHAMAS · PRODUCTION STUDIO</div><h1>${title}</h1><p>${sub}</p></div><div class="head-right">${extra||'<span class="snapshot">Source snapshot · 16 Nov 2026</span>'}</div></div>`+notesEditor('module:'+view,'Notes for '+NAV.find(n=>n[0]===view)[1])}
function navigate(){let hash=location.hash.slice(1)||'overview';const [v,param]=hash.split('/');view=NAV.some(n=>n[0]===v)?v:'overview';filters={query:'',island:'all',format:'all',stage:'all',page:1};if(view==='listings'&&param)filters.island=param;$('#sidebar').classList.remove('open');render()}
function render(){closeModal(false);$('#nav').innerHTML=NAV.map(([id,label,n])=>`<a href="#${id}" class="nav-item ${id===view?'active':''}" ${id===view?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${n?`<span class="nav-count">${n}</span>`:''}</a>`).join('');$('#crumb').textContent=NAV.find(n=>n[0]===view)[1];$('#main').innerHTML=({overview, listings,communities,scripts,routes,faq,launch,files,settings}[view])();}
const CAREER_SOURCE='https://www.breabahamas.com/download/1794317811.pdf';
const CAREER_FIELDS=['licenceDate','practiceStart','sales','rentals','volume','asOf'];
function nassauToday(now=new Date()){
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Nassau',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
  return ['year','month','day'].map(type=>parts.find(p=>p.type===type).value).join('-');
}
function calendarDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return null;const d=new Date(value+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value?d:null}
function careerRecord(raw=state.career){return Object.fromEntries(CAREER_FIELDS.map(k=>[k,raw?.[k]??'']))}
function validateCareer(raw,today=nassauToday()){
  const c=careerRecord(raw);
  for(const key of ['licenceDate','practiceStart','asOf']){
    if(c[key]==='')continue;
    if(!calendarDate(c[key]))throw Error('Enter a valid date.');
    if(c[key]>today)throw Error('Recorded dates cannot be in the future.');
  }
  if(c.practiceStart&&!c.licenceDate)throw Error('Add your licence date before the start of practice.');
  if(c.practiceStart&&c.practiceStart<c.licenceDate)throw Error('Continuous licensed practice cannot start before your licence date.');
  for(const key of ['sales','rentals','volume']){
    if(c[key]==='')continue;
    if(!['string','number'].includes(typeof c[key])||String(c[key]).trim()==='')throw Error('Enter a valid transaction total.');
    const n=Number(c[key]);
    if(!Number.isFinite(n)||n<0||n>(key==='volume'?1e12:100000))throw Error('Enter a valid non-negative transaction total.');
    if(key!=='volume'&&!Number.isInteger(n))throw Error('Sales and rentals must be whole numbers.');
    if(key==='volume'&&Math.abs(n*100-Math.round(n*100))>0.01)throw Error('Enter the transaction value with at most two decimal places.');
    c[key]=key==='volume'?Math.round(n*100)/100:n;
  }
  if(['sales','rentals','volume'].every(k=>c[k]===''))c.asOf='';
  if(['sales','rentals','volume'].some(k=>c[k]!=='')&&!c.asOf)throw Error('Add the date these transaction totals were checked.');
  if(c.asOf&&c.practiceStart&&c.asOf<c.practiceStart&&['sales','rentals','volume'].some(k=>c[k]!==''))throw Error('Transaction totals must be dated on or after your practice start.');
  return c;
}
function careerProgress(c,today=nassauToday()){
  const start=calendarDate(c.practiceStart),now=calendarDate(today);
  if(!start||!now)return {target:'',percent:0,days:null,reached:false,elapsedMonths:0};
  // Calendar anniversary; a leap-day start rolls forward to 1 March in a non-leap year.
  const target=new Date(start);target.setUTCFullYear(target.getUTCFullYear()+5);
  const percent=Math.max(0,Math.min(100,(now-start)/(target-start)*100));
  const months=Math.max(0,(now.getUTCFullYear()-start.getUTCFullYear())*12+now.getUTCMonth()-start.getUTCMonth()-(now.getUTCDate()<start.getUTCDate()?1:0));
  return {target:target.toISOString().slice(0,10),percent,days:Math.max(0,Math.ceil((target-now)/86400000)),reached:now>=target,elapsedMonths:months};
}
function careerDate(value){const d=calendarDate(value);return d?new Intl.DateTimeFormat('en-GB',{timeZone:'UTC',day:'numeric',month:'short',year:'numeric'}).format(d):'Date to add'}
function careerTimeline(){
  const c=careerRecord(),p=careerProgress(c),years=Math.floor(p.elapsedMonths/12),months=p.elapsedMonths%12;
  const number=v=>v===''?'—':Number(v).toLocaleString('en-US');
  return `<section class="career-timeline" aria-labelledby="career-heading"><div class="career-heading"><div><div class="eyebrow">YOUR PROFESSIONAL JOURNEY</div><h2 id="career-heading">Career timeline</h2></div><button class="button" data-action="career-edit">${c.licenceDate?'Update timeline':'Set up timeline'} ↗</button></div><ol class="career-milestones"><li class="career-step ${c.licenceDate?'recorded':''}"><span class="career-dot" aria-hidden="true">01</span><div class="career-step-copy"><h3>Licence granted</h3><div class="career-date">${c.licenceDate?careerDate(c.licenceDate):'Add your licence date'}</div><p>${c.practiceStart?'Continuous practice from '+careerDate(c.practiceStart):'Record when you started working under a broker.'}</p></div></li><li class="career-step"><span class="career-dot" aria-hidden="true">02</span><div class="career-step-copy"><h3>Sales accrued</h3><div class="career-totals"><span><b>${number(c.sales)}</b> / 20 sales</span><span><b>${number(c.rentals)}</b> / 5 rentals</span></div><p class="career-volume">${c.volume===''?'Add qualifying transaction value':'$'+Number(c.volume).toLocaleString('en-US',{maximumFractionDigits:2})+' / $3.5m transaction value'}</p><small>${c.asOf?'Totals checked '+careerDate(c.asOf):'Record completed transactions'}</small></div></li><li class="career-step ${p.reached?'recorded':''}"><span class="career-dot" aria-hidden="true">03</span><div class="career-step-copy"><h3>Five-year milestone</h3><div class="career-date">${p.target?careerDate(p.target):'Add your practice start date'}</div><p>${p.reached?'Time milestone reached · eligibility review still required':p.target?p.days.toLocaleString()+' days to your projected milestone':'Your target date updates from your continuous practice start.'}</p></div></li></ol><div class="career-progress-head"><span>${p.target?`${years} ${years===1?'year':'years'}${months?' '+months+' '+(months===1?'month':'months'):''} of continuous practice`:'Five consecutive years of practice'}</span><span>${p.target?Math.floor(p.percent)+'% of time milestone':'Add dates to begin'}</span></div><div class="career-progress" role="progressbar" aria-label="Five-year practice milestone" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.floor(p.percent)}"><span style="width:${p.percent.toFixed(2)}%"></span></div><div class="career-years" aria-hidden="true"><span>Start</span><span>Year 1</span><span>Year 2</span><span>Year 3</span><span>Year 4</span><span>Year 5</span></div><p class="career-caveat">Projected broker eligibility milestone. BREA also requires education, supporting evidence and Board approval. Transaction totals must cover the five years before application. <a href="${CAREER_SOURCE}" target="_blank" rel="noopener">Requirements · 27 Oct 2026 ↗</a></p></section>`;
}
function careerModal(){
  const c=careerRecord(),today=nassauToday();
  openModal('Update your career timeline','Your licence, continuous practice and completed transactions',`<form id="career-form"><div class="career-form-grid"><div class="form-row"><label for="career-licenceDate">Licence granted date</label><input type="date" id="career-licenceDate" name="licenceDate" max="${today}" value="${esc(c.licenceDate)}"></div><div class="form-row"><label for="career-practiceStart">Continuous practice started</label><input type="date" id="career-practiceStart" name="practiceStart" max="${today}" value="${esc(c.practiceStart)}"><p class="small muted">Start of your current uninterrupted period working as a licensed salesperson under a broker. Update this after a break in practice.</p></div><div class="form-row"><label for="career-sales">Completed sales</label><input type="number" id="career-sales" name="sales" min="0" max="100000" step="1" placeholder="Not entered" value="${esc(c.sales)}"></div><div class="form-row"><label for="career-rentals">Completed rentals</label><input type="number" id="career-rentals" name="rentals" min="0" max="100000" step="1" placeholder="Not entered" value="${esc(c.rentals)}"></div><div class="form-row"><label for="career-volume">Qualifying transaction value ($)</label><input type="number" id="career-volume" name="volume" min="0" max="1000000000000" step="0.01" placeholder="Not entered" value="${esc(c.volume)}"><p class="small muted">Use the value confirmed for your BREA transaction record, not commissions. Confirm valuation and currency with your broker.</p></div><div class="form-row"><label for="career-asOf">Transaction totals checked on</label><input type="date" id="career-asOf" name="asOf" max="${today}" value="${esc(c.asOf||today)}"><p class="small muted">Enter totals for the preceding five years. Recheck this window when you apply.</p></div></div><p class="small muted">These totals are entered by you; they do not sync with MLS. Saved in this browser and included in Export progress.</p><p id="career-error" class="career-error" role="alert"></p><div class="modal-actions"><button type="submit" class="button primary">Save timeline</button><button type="button" class="button" data-action="close">Cancel</button></div></form>`);
}
function saveCareer(raw){state.career=validateCareer(raw);return save()}
document.addEventListener('submit',e=>{
  if(e.target.id!=='career-form')return;
  e.preventDefault();
  try{
    const raw=Object.fromEntries(CAREER_FIELDS.map(k=>[k,e.target.elements.namedItem(k).value]));
    if(!saveCareer(raw)){$('#career-error').textContent='Could not save. Export progress before closing to keep these details.';return}
    render();toast('Career timeline saved on this browser.');
  }catch(error){$('#career-error').textContent=error.message||'Check your timeline details.'}
});

function overview(){const ready=D.assets.filter(a=>stage(a.id)==='Ready to film').length,done=D.assets.filter(a=>['Filmed','Editing','Review','Approved','Published'].includes(stage(a.id))).length;return careerTimeline()+head('Every story starts here.','Your filming plan, property intelligence and creative work — in one place.')+`<div class="stats">${[[29,'Properties to explore','listings'],[12,'Community guides','communities'],[115,'Planned video edits','scripts'],[ready,'Ready to film','play']].map(([n,l,i])=>`<div class="stat"><div><div class="stat-number">${n}</div><div class="stat-label">${l}</div></div><div class="stat-icon">${icon(i)}</div></div>`).join('')}</div><section class="hero"><div class="hero-copy"><div class="eyebrow">THE FEATURE FILM · EASTERN ROAD</div><h2>The Rum Club</h2><p>Poolside living, an ocean outlook and a separate guest suite. Your signature property story, with every scene ready to capture.</p><div class="hero-meta"><div><b>67963</b>MLS number</div><div><b>3 edits</b>One filming day</div><div><b>D05</b>Dedicated route</div></div><div class="hero-actions"><button class="button light" data-action="asset" data-id="L01-H">Open feature script <span>↗</span></button><button class="button outline-light" data-action="listing" data-id="L01">Property details</button></div></div><div class="hero-art" aria-hidden="true"><div class="feature-frame"><div class="small-label">A SIENNA EVANS PROPERTY STORY</div><div class="serif">The Rum<br>Club.</div><div class="film-label"><span>EASTERN ROAD</span><span>01 / 29</span></div></div></div></section><div class="grid-two"><section class="panel"><div class="panel-head"><h2>Plan your next shoot</h2><a class="text-link" href="#routes">All routes ↗</a></div>${['D05','D03','D06'].map(id=>{const r=D.routes.find(r=>r.id===id);return `<div class="route-row"><div class="route-badge">${r.id}</div><div class="row-content"><div class="row-title">${r.name}</div><div class="row-sub">${r.listings.split(' ').length} ${r.listings.split(' ').length===1?'property':'properties'} · ${state.routeDates[id]?esc(state.routeDates[id]):'Date not set'}</div></div><button class="icon-button" data-action="route" data-id="${id}" aria-label="Open ${esc(r.name)}">↗</button></div>`}).join('')}</section><section class="panel"><div class="panel-head"><h2>Before the camera rolls</h2><span class="pill warning">Review notes</span></div>${[['L20','Caves Point','Conflicting asking prices'],['L14','Still Lake','Pre-construction capture'],['L29','Sola Vista Estate','Redevelopment land, not a home tour']].map(([id,n,t])=>`<div class="attention-row"><div class="attention-icon">!</div><div class="row-content"><div class="row-title">${n}</div><div class="row-sub">${t}</div></div><button class="text-link" data-action="listing" data-id="${id}">Review ↗</button></div>`).join('')}</section></div><div class="section-head"><h2>Beyond Nassau</h2><span class="small muted">Three properties. Each island.</span></div><div class="island-grid">${[['ABACO','Abaco','Waterfront homes & acreage'],['ELEUTHERA','Eleuthera','Beach houses & Banks Road'],['EXUMA','Exuma','Coastal homes & new possibilities']].map(([id,n,s])=>`<a href="#listings/${id}" class="island-tile"><div><h3>${n}</h3><p>${s}</p></div><span>↗</span></a>`).join('')}</div><div class="section-head"><h2>From capture to conversation</h2><span class="small muted">${done} / 115 edits captured</span></div><div class="panel"><div class="panel-body"><p class="small muted">Discover → compare communities → explore homes → answer buyer questions → consultation → viewing.</p><div class="progress-track"><span style="width:${done/115*100}%"></span></div><p class="small muted" style="margin-top:13px">Use each script’s message keyword to connect enquiries to the content that inspired them.</p></div></div>`}
function searchbar(extra=''){return `<div class="toolbar"><div class="search-box">${icon('search')}<input type="search" id="search" aria-label="Search ${view}" placeholder="${view==='listings'?'Search property, area or MLS number…':view==='scripts'?'Search scripts, keywords or subject…':'Search communities…'}" value="${esc(filters.query)}"></div>${extra}</div>`}
function options(arr,selected){return arr.map(([v,l])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(l)}</option>`).join('')}
function paginated(items,size,card){const pages=Math.max(1,Math.ceil(items.length/size));filters.page=Math.min(filters.page,pages);return `<div class="result-line">${items.length} results · Page ${filters.page} of ${pages}</div>${items.length?`<div class="card-grid">${items.slice((filters.page-1)*size,filters.page*size).map(card).join('')}</div>`:`<div class="empty"><h2>No matches yet.</h2><p class="muted">Try a different search or clear your filters.</p><button class="button" data-action="clear-filters">Clear filters</button></div>`}${pages>1?`<div class="pagination"><button class="button" data-action="page" data-dir="-1" ${filters.page===1?'disabled':''}>← Previous</button><span>${filters.page} / ${pages}</span><button class="button" data-action="page" data-dir="1" ${filters.page===pages?'disabled':''}>Next →</button></div>`:''}`}
function listingCard(r){return `<article class="listing-card"><div class="card-top"><span class="card-code">${r.id} / MLS ${r.mls}</span>${pill(r.type,r.type==='Pre-construction'?'warning':'')}</div><div class="card-body"><span class="card-area">${esc(r.area)}</span><h3>${esc(r.name)}</h3><div class="price">${r.price?'$'+Number(r.price).toLocaleString('en-US'):'Price confirmation needed'}<small>${r.price?'Public asking price · confirm currency':'$1,495,000 / $1,550,000 conflict'}</small></div><p class="card-description">${esc(r.feature)}</p><div class="small muted">${r.beds==='Not applicable'?esc(r.lot):esc(r.beds)+' beds · '+esc(r.baths)+' baths'}</div></div><div class="card-bottom"><button class="text-link" data-action="listing-notes" data-id="${r.id}" aria-label="Notes for ${esc(r.name)}">✎ Notes</button><button class="text-link" data-action="listing" data-id="${r.id}">Open filming card ↗</button></div></article>`}
function listings(){const q=filters.query.toLowerCase(),items=D.listings.filter(r=>(filters.island==='all'||getGroup(r)===filters.island)&&(filters.format==='all'||r.type===filters.format)&&[r.name,r.area,r.mls,r.feature,r.id].join(' ').toLowerCase().includes(q));return head('Property collection','A filming card for every property, from the first exterior shot to the final invitation.')+searchbar(`<select id="island-filter" aria-label="Filter island">${options([['all','All islands'],['NASSAU','Nassau / Paradise Island'],['ABACO','Abaco'],['ELEUTHERA','Eleuthera'],['EXUMA','Exuma']],filters.island)}</select><select id="format-filter" aria-label="Filter property type">${options([['all','All property types'],...['Home','Condo','Land','Pre-construction'].map(v=>[v,v])],filters.format)}</select>`)+`<div class="callout">Public Coldwell Banker website shortlist: 11 pages name CB agents; 18 are syndicated listings. Current availability and filming access require agent confirmation.</div><div id="filtered-content">${paginated(items,9,listingCard)}</div>`}
function communities(){const q=filters.query.toLowerCase(),items=D.communities.filter(c=>[c.name,c.location,c.tier,c.schools,c.restaurants].join(' ').toLowerCase().includes(q));return head('Life around the listing','Twelve Nassau and Paradise Island guides, shaped around real routines and ownership questions.')+searchbar()+`<div id="filtered-content">${paginated(items,12,c=>`<article class="community-card"><div class="card-top"><span class="card-code">${c.id} / COMMUNITY GUIDE</span><span class="small">3 edits</span></div><div class="card-body"><div class="card-area">${esc(c.location)}</div><h3>${esc(c.name)}</h3>${pill(c.tier)}<div class="mini-label">Explore</div><p class="small muted">${esc(c.lifestyle)}</p><div class="mini-label">Dining stops</div><p class="small muted">${esc(c.restaurants)}</p></div><div class="card-bottom"><button class="text-link" data-action="community-notes" data-id="${c.id}" aria-label="Notes for ${esc(c.name)}">✎ Notes</button><button class="text-link" data-action="community" data-id="${c.id}">Open guide ↗</button></div></article>`)}</div>`}
function scripts(){const q=filters.query.toLowerCase(),items=D.assets.filter(a=>(filters.format==='all'||a.kind===filters.format)&&(filters.stage==='all'||stage(a.id)===filters.stage)&&[a.id,a.script,a.cta,subject(a.subject),a.kind].join(' ').toLowerCase().includes(q));return head('Words, ready for the camera.','Spoken scripts, captions, shot directions and review notes for all 115 planned edits.')+searchbar(`<select id="format-filter" aria-label="Filter video format">${options([['all','All video formats'],...[...new Set(D.assets.map(a=>a.kind))].map(k=>[k,k])],filters.format)}</select><select id="stage-filter" aria-label="Filter production status">${options([['all','All production stages'],...STAGES.map(s=>[s,s])],filters.stage)}</select>`)+`<div id="filtered-content">${paginated(items,12,a=>`<article class="asset-card"><div class="card-top"><span class="card-code">${a.id}</span>${pill(a.duration)}</div><div class="card-body"><div class="card-area">${esc(a.kind)}</div><h3>${esc(subject(a.subject))}</h3><p class="script-excerpt">${esc(a.script)}</p><label class="mini-label" for="stage-${a.id}">Production status</label><select id="stage-${a.id}" data-status="${a.id}" aria-label="Status for ${a.id}">${options(STAGES.map(s=>[s,s]),stage(a.id))}</select></div><div class="card-bottom"><button class="text-link" data-action="asset" data-id="${a.id}">Open script ↗</button><button class="button" data-action="copy-caption" data-id="${a.id}">Copy caption</button></div></article>`)}</div>`}
function routes(){const r=D.routes.find(x=>x.id===selectedRoute)||D.routes[0],stops=r.listings.split(' ').filter(Boolean).map(id=>D.listings.find(x=>x.id===id)),query=stops[0]?.map_query||'Nassau Bahamas';return head('A considered route. A better shoot.','Geographic shoot blocks with property stops, community coverage and practical timing.')+`<div class="route-layout"><div class="route-list">${D.routes.map(x=>`<button class="route-choice ${x.id===r.id?'selected':''}" data-action="select-route" data-id="${x.id}"><span class="card-code">${x.id}</span><strong>${esc(x.name)}</strong><small>${x.listings?x.listings.split(' ').length+' properties':'18 FAQ answers'}</small></button>`).join('')}</div><section class="panel"><div class="panel-head"><div><div class="eyebrow">SHOOT BLOCK ${r.id}</div><h2>${esc(r.name)}</h2></div>${r.id!=='F01'?`<a class="button" href="${safeUrl(r.url)}" target="_blank" rel="noopener">Open route ↗</a>`:''}</div><div class="panel-body"><div class="callout">${esc(r.note)}</div><div class="form-row"><label for="route-date">Your planned shoot date</label><input id="route-date" type="date" value="${esc(state.routeDates[r.id]||'')}" data-route="${r.id}"><p class="small muted" style="margin-top:6px">A planning date only; no booking or invitation is sent.</p></div>${notesEditor('route:'+r.id,'Shoot notes for '+r.name,'Crew, timings, access arrangements, weather alternatives…')}<div class="mini-label">Property stops · final order to confirm</div><ol class="stop-list">${stops.map((s,i)=>`<li><span class="stop-number">${i+1}</span><div class="row-content"><div class="row-title">${esc(s.name)}</div><div class="row-sub">${s.id} · MLS ${s.mls} · ${esc(s.area)}</div></div><button class="text-link" data-action="listing" data-id="${s.id}">Details ↗</button></li>`).join('')||'<li>Quiet studio, two cameras, Sienna hosting. Open Buyer FAQ for all answers.</li>'}</ol><p class="small muted" style="margin-top:18px">Area orientation only. Obtain exact unit, lot and gate pins from the agents. Travel and weather buffers are additional.</p></div><div id="route-map-slot" class="map-placeholder"><div class="eyebrow">AREA ORIENTATION</div><p>Load the map when you need it.</p><button class="button" data-action="load-map" data-id="${r.id}">Load area map ↗</button></div><div class="panel-body"><a class="source-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}" target="_blank" rel="noopener">Open area map if the embedded map is unavailable ↗</a></div></section></div>`}
function loadRouteMap(id){const route=D.routes.find(r=>r.id===id);if(!route)return;const firstId=route.listings.split(' ').find(Boolean),query=D.listings.find(r=>r.id===firstId)?.map_query||'Nassau Bahamas',slot=$('#route-map-slot');if(!slot)return;slot.className='';slot.innerHTML=`<iframe class="route-map" title="Area orientation for ${esc(route.name)}" referrerpolicy="no-referrer-when-downgrade" src="https://maps.google.com/maps?q=${encodeURIComponent(query)}&output=embed"></iframe>`}
function faq(){return head('Buying in The Bahamas','A sit-down filming session that makes the buying process approachable, one question at a time.',`<button class="button primary" data-action="asset" data-id="F00">Full session script ↗</button>`)+`<div class="grid-two"><section class="panel"><div class="panel-body"><div class="eyebrow">THE SESSION</div><h2>18 questions. Four focused hours.</h2><p class="small muted" style="margin-top:13px">Two camera angles, soft light and a quiet room. Record each answer separately with a clean opener and closer. Assemble the full guide from the approved clips.</p><div class="modal-actions"><button class="button" data-action="asset" data-id="F00">Intro & outro</button><button class="button" data-action="route" data-id="F01">Session planning</button></div></div></section><section class="panel"><div class="panel-body"><div class="eyebrow">REVIEW BEFORE RELEASE</div><h2>Clear guidance, current facts.</h2><p class="small muted" style="margin-top:13px">Legal, tax, immigration and financing answers have their own review notes. Confirm the rules for the individual transaction; the scripts avoid fixed tax rates and automatic residency promises.</p></div></section></div><div class="faq-grid">${D.faqs.map(f=>`<details class="faq-item"><summary><span class="card-code">${f.id}</span><span>${esc(f.question)}</span></summary><div class="faq-answer"><p>${esc(f.answer)}</p><p class="small muted" style="margin-top:14px">Review: ${esc(f.gate)}</p>${notesEditor('asset:'+f.id,'Notes for '+f.id,'Questions to clarify, answer changes, best take…')}<button class="button" data-action="asset" data-id="${f.id}">Open filming script ↗</button></div></details>`).join('')}</div>`}
function launch(){return head('A steady rhythm of stories.','A proposed nine-week opening queue: five short videos each week, released only when ready.')+`<div class="callout">This queue is a production plan. No posts are automatically scheduled or published. Use the original asset keyword to record where enquiries came from.</div><section class="panel"><div class="panel-head"><h2>The first 45 short videos</h2><a class="text-link" href="#scripts">View script library ↗</a></div>${Array.from({length:9},(_,i)=>`<div class="launch-week"><div class="week-label">WEEK ${String(i+1).padStart(2,'0')}</div><div class="week-assets">${D.launch.filter(r=>r.week===i+1).map(r=>`<button data-action="asset" data-id="${r.asset}" title="${esc(subject(D.assets.find(a=>a.id===r.asset).subject))}">${r.slot}. ${r.asset} · ${esc(stage(r.asset))}</button>`).join('')}</div></div>`).join('')}</section><div class="grid-two" style="margin-top:24px"><section class="panel"><div class="panel-body"><h2>Make the next step easy.</h2><p class="small muted" style="margin-top:14px">Discover → community comparison → property detail → buyer FAQ → consultation → viewing.</p><p class="small muted" style="margin-top:14px">Qualify enquiries by island, budget, intended use, timeline and three must-haves. Track consultations and viewings alongside reach and saves.</p></div></section><section class="panel"><div class="panel-body"><h2>A warm first reply.</h2><p class="small muted" style="margin-top:14px">“Thank you for your interest. Which island are you considering, what budget feels comfortable, how will you use the property, and what is your timeline? Share your top three must-haves and we can arrange a call.”</p></div></section></div>`}
function files(){return head('Your production desk.','The original working documents, available together with the live dashboard.')+`<div class="file-grid">${[['DOCX','Master production funnel','55-page camera-side manual with listing cards, scripts, captions and the complete filming workflow.','Bahamas_Master_Production_Funnel.docx'],['XLSX','Production tracker','Nine tabs covering all listings, communities, scripts, routes, review notes and launch slots.','Bahamas_Production_Tracker.xlsx'],['HTML','Production map','The standalone searchable location navigator and proposed area-route links.','Production_Map.html']].map(([ext,name,desc,f])=>`<article class="file-card"><div class="file-icon">${ext}</div><h3>${name}</h3><p>${desc}</p><a class="button" href="./downloads/${f}" download>Download ${ext} ↓</a></article>`).join('')}</div><div class="callout" style="margin-top:24px">These documents preserve the original planning edition. Changes made to dashboard statuses, notes and dates are saved separately in this browser. Export progress to keep a transferable backup.</div><section class="panel"><div class="panel-head"><h2>Research sources</h2><span class="small muted">16 November 2026</span></div><div class="panel-body">${Object.entries(D.sources).map(([id,[title,url]])=>`<a class="source-link" target="_blank" rel="noopener" href="${safeUrl(url)}">${esc(id)} · ${esc(title)} ↗</a>`).join('')}</div></section>`}
function settings(){return head('Built around your brand.','Your approved identity, workspace data and deployment notes.')+`<section class="panel"><div class="panel-head"><h2>Deep coastal luxury</h2><span class="pill">Official palette · v1.0</span></div><div class="panel-body"><div class="palette">${[['Midnight Navy','#071B2C'],['Coldwell Banker Blue','#012169'],['Deep Ocean','#123F43'],['Warm Ivory','#F4F0E8'],['Champagne','#B5A17A']].map(([n,c])=>`<div><div class="swatch-color" style="background:${c};border:1px solid #071b2c15"></div><p>${n}</p><code>${c}</code></div>`).join('')}</div><div class="divider"></div><div class="grid-two"><div><div class="mini-label">Display typography</div><div class="serif" style="font-size:34px">Bodoni Moda</div><p class="small muted">Property headlines and the Bahamas Real Estate Pilot title.</p></div><div><div class="mini-label">Body typography</div><div style="font-size:30px;margin-bottom:6px">Roboto</div><p class="small muted">Descriptions, prices, scripts and practical details.</p></div></div><a class="source-link" href="https://chatgpt.com/library?file_id=libfile_6651d008569081918c55aff6431a66e8&account_id=personal" target="_blank" rel="noopener">Open official brand reference ↗</a><p class="small muted">Personal brand extension for Sienna Evans. Any brokerage logo must be supplied in its approved form; this dashboard does not recreate it.</p></div></section><div class="settings-grid" style="margin-top:22px"><section class="panel"><div class="panel-head"><h2>Your workspace data</h2></div><div class="panel-body"><p class="small muted">Statuses, shot ticks, notes and shoot dates are stored on this browser. They do not automatically synchronise across devices or team members. Export a backup before switching browsers; import it on the new device.</p><div class="modal-actions"><button class="button primary" data-action="export">Export progress</button><button class="button" data-action="import">Import backup</button></div><p class="small muted" style="margin-top:15px">Import replaces the current browser’s progress after confirmation. The listing source catalogue stays unchanged.</p></div></section><section class="panel"><div class="panel-head"><h2>Your own domain</h2></div><div class="panel-body"><p class="small muted">A custom domain can point to this dashboard after hosting and DNS are configured. Save the address you intend to use below.</p><div class="form-row" style="margin-top:16px"><label for="domain-note">Planned domain or subdomain</label><input id="domain-note" placeholder="studio.yourdomain.com" value="${esc(state.domain)}" maxlength="253"><p class="small muted" style="margin-top:8px">A planning note only. This field does not configure DNS.</p></div><p class="small muted">This is an internal production workspace. Keep access restricted when hosting it on your domain.</p></div></section></div>`}

function openModal(title,subtitle,body){clearInterval(teleTimer);teleTimer=null;lastFocus=document.activeElement;$('#modal-content').innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;$('#modal').hidden=false;document.body.classList.add('modal-open');document.body.style.overflow='hidden';$('#modal [data-action="close"]').focus()}
function closeModal(restore=true){clearInterval(teleTimer);teleTimer=null;$('#modal').hidden=true;document.body.classList.remove('modal-open');document.body.style.overflow='';modalId=null;if(restore&&lastFocus?.isConnected)lastFocus.focus()}
function listingModal(id){const r=D.listings.find(x=>x.id===id);if(!r)return;const a=D.assets.filter(x=>x.subject===id),p=prop(id);modalId=id;openModal(r.name,`${id} · MLS ${r.mls} · ${r.area}`,`<div class="modal-grid"><div><p>${esc(r.feature)}</p>${notesEditor('property:'+id,'Property notes for '+r.name,'Filming ideas, missing information, questions and changes…')}<div class="fact-grid">${[['Ask observed',r.price_text],['Bedrooms',r.beds],['Bathrooms',r.baths],['Area shown',r.floor],['Lot shown',r.lot],['Shoot block',r.route]].map(([l,v])=>`<div class="fact"><small>${l}</small><b>${esc(v)}</b></div>`).join('')}</div><div class="callout warning">${esc(r.verify)}</div><div class="modal-section"><h3>Capture these details</h3><p class="shot-detail">${esc(r.shots.split(';').map(s=>'• '+s.trim()).join('\n'))}</p></div><div class="modal-section"><h3>Scripts for this property</h3><div class="inline-actions">${a.map(x=>`<button class="button" data-action="asset" data-id="${x.id}">${x.id} · ${esc(x.kind)}</button>`).join('')}</div></div><a class="source-link" href="${safeUrl(r.url)}" target="_blank" rel="noopener">Open public listing source ↗</a><a class="source-link" href="${safeUrl(r.map_url)}" target="_blank" rel="noopener">Open area map search ↗</a><p class="small muted">${esc(r.attribution)}. Publicly advertised on ${D.asof}; current status unconfirmed.</p></div><aside><h3>Agent confirmation</h3><p class="small muted" style="margin:8px 0">Record what has been confirmed for this shoot.</p>${[['status','Current availability checked'],['price','Price and currency confirmed'],['access','Owner / tenant filming permission'],['pin','Exact unit, lot or gate pin received']].map(([k,l])=>`<label class="check"><input type="checkbox" data-property-check="${id}" data-key="${k}" ${p[k]?'checked':''}><span>${l}</span></label>`).join('')}<div class="form-row" style="margin-top:17px"><label for="agent-${id}">Agent, confirmation date and current details</label><textarea id="agent-${id}" data-property-notes="${id}" placeholder="Who confirmed it, when, current price/currency, access details…" maxlength="10000">${esc(p.notes||'')}</textarea></div><button class="button" data-action="route" data-id="${r.route}">View shoot route ↗</button></aside></div>`)}
function communityModal(id){const c=D.communities.find(x=>x.id===id);if(!c)return;modalId=id;openModal(c.name,`${c.id} · ${c.location}`,`<div class="callout">${esc(c.note)}</div>${notesEditor('community:'+id,'Community notes for '+c.name,'Places to film, local contacts, questions and changes…')}<div class="modal-grid"><div><div class="modal-section"><h3>What to capture</h3><p>${esc(c.lifestyle)}</p><p class="small muted" style="margin-top:10px">Entrance → streetscape → listing exterior → permitted school exterior → dining → lifestyle → buyer question and close.</p></div><div class="modal-section"><h3>Selected asking examples</h3><p class="small muted">${esc(c.examples)}</p><p class="small muted" style="margin-top:8px">Individual public asks, not market averages. Recheck prices before publishing.</p></div><div class="modal-section"><h3>Three ready-to-record scripts</h3><div class="inline-actions">${['O','L','Q'].map((s,i)=>`<button class="button" data-action="asset" data-id="${id}-${s}">${['Guide','Day in the life','Buyer question'][i]} ↗</button>`).join('')}</div></div><div class="modal-section"><h3>Featured properties</h3><div class="inline-actions">${c.listing_ids.split(' ').map(l=>`<button class="button" data-action="listing" data-id="${l}">${esc(subject(l))}</button>`).join('')}</div></div></div><aside><div class="modal-section"><h3>Schools to research</h3><p class="small muted">${esc(c.schools)}</p></div><div class="modal-section"><h3>Dining stops</h3><p class="small muted">${esc(c.restaurants)}</p></div><div class="modal-section"><h3>The buyer question</h3><p class="small muted">${esc(c.tradeoff)}</p></div><a class="source-link" target="_blank" rel="noopener" href="${safeUrl(c.map_url)}">Open community map ↗</a>${c.source_ids.split(' ').map(s=>`<a class="source-link" target="_blank" rel="noopener" href="${safeUrl(D.sources[s][1])}">${esc(D.sources[s][0])} ↗</a>`).join('')}</aside></div>`)}
function assetShots(a){if(a.subject==='FAQ')return [['Q01','Camera A medium and camera B close'],['Q02','Question card and clean spoken answer'],['Q03','Second opener and clean close'],['Q04','Sound check and 30 seconds room tone']];if(a.subject.startsWith('C'))return [['M01','Area and entrance'],['M02','Host hook'],['M03','Streetscape'],['M04','Selected listing exterior'],['M05','Permitted school exterior'],['M06','Dining exterior or detail'],['M07','Lifestyle footage'],['M08','Buyer comparison and CTA']];return D.shots.filter(s=>s[0]!=='S14').map(s=>[s[0],s[1]])}
function assetModal(id,tele=false){const a=D.assets.find(x=>x.id===id);if(!a)return;modalId=id;openModal(subject(a.subject),`${a.id} · ${a.kind} · ${a.duration}`,`${tele?`<div class="teleprompter"><div class="tele-controls"><button class="button light" data-action="tele-play">Start scrolling</button><button class="button outline-light" data-action="tele-reset">Back to top</button><label>Size <input id="tele-size" type="range" min="22" max="54" value="31" aria-label="Teleprompter text size"></label><label>Speed <input id="tele-speed" type="range" min="8" max="80" value="25" aria-label="Teleprompter scroll speed"></label></div><div class="tele-text" id="tele-text">${esc(a.script)}</div></div><div class="modal-actions"><button class="button" data-action="asset" data-id="${a.id}">Back to script card</button></div>`:`<div class="modal-grid"><div><div class="modal-section"><div class="section-head" style="margin-top:0"><h3>Spoken script</h3><span class="pill">${esc(a.cta)}</span></div><div class="script-box">${esc(a.script)}</div><div class="modal-actions"><button class="button primary" data-action="tele" data-id="${a.id}">Filming view ↗</button><button class="button" data-action="copy-script" data-id="${a.id}">Copy script</button><button class="button" data-action="print">Print card</button></div></div><div class="modal-section"><h3>Instagram caption</h3><div class="caption-box">${esc(a.caption)}</div><div class="modal-actions"><button class="button" data-action="copy-caption" data-id="${a.id}">Copy caption</button></div></div><div class="modal-section"><h3>Shot directions</h3><p class="shot-detail">${esc(a.shots)}</p></div><div class="callout warning"><strong>Before release:</strong> ${esc(a.gate)}</div>${a.source.split('\n').filter(Boolean).map((u,i)=>`<a class="source-link" href="${safeUrl(u)}" target="_blank" rel="noopener">Reference source ${i+1} ↗</a>`).join('')}</div><aside><h3>Production status</h3><select class="status-select" data-status="${a.id}" aria-label="Production status">${options(STAGES.map(s=>[s,s]),stage(a.id))}</select><p class="small muted">Mark ready only after the review notes and filming access are resolved.</p><div class="divider"></div><h3>Capture checklist</h3>${assetShots(a).map(([k,l])=>`<label class="check"><input type="checkbox" data-shot="${a.id}" data-key="${k}" ${as(a.id).shots?.[k]?'checked':''}><span><b>${k}</b> ${esc(l)}</span></label>`).join('')}${notesEditor('asset:'+a.id,'Take log and edit notes','Best take, missing shot, edit direction…',true)}</aside></div>`}`)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'Copied to clipboard.':'Copy unavailable here. Select the script text to copy.')}}
function exportProgress(){const blob=new Blob([JSON.stringify({application:'sienna-bahamas-production',version:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Bahamas_Real_Estate_Pilot_Progress_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Progress backup downloaded.')}
function validImport(j){if(j.application!=='sienna-bahamas-production'||j.version!==1||!j.data||typeof j.data!=='object')throw Error('This is not a dashboard progress backup.');const out={assets:{},properties:{},routeDates:{},notes:{},domain:''};for(const [id,v] of Object.entries(j.data.assets||{})){if(!D.assets.some(a=>a.id===id)||!v||typeof v!=='object')continue;out.assets[id]={};if(STAGES.includes(v.status))out.assets[id].status=v.status;if(typeof v.notes==='string')out.assets[id].notes=v.notes.slice(0,10000);out.assets[id].shots=Object.fromEntries(Object.entries(v.shots||{}).filter(([k,val])=>/^[SMQ]\d\d$/.test(k)&&typeof val==='boolean'));}for(const [id,v]of Object.entries(j.data.properties||{})){if(!D.listings.some(r=>r.id===id)||!v||typeof v!=='object')continue;out.properties[id]={};for(const k of ['status','price','access','pin'])out.properties[id][k]=v[k]===true;if(typeof v.notes==='string')out.properties[id].notes=v.notes.slice(0,10000);}for(const [id,v]of Object.entries(j.data.routeDates||{}))if(D.routes.some(r=>r.id===id)&&/^\d{4}-\d{2}-\d{2}$/.test(v))out.routeDates[id]=v;for(const [key,v]of Object.entries(j.data.notes||{})){if(!noteKeyAllowed(key)||key.startsWith('asset:')||!v||typeof v.text!=='string')continue;out.notes[key]={text:v.text.slice(0,10000),updatedAt:typeof v.updatedAt==='string'&&Number.isFinite(Date.parse(v.updatedAt))?new Date(v.updatedAt).toISOString():''}}out.career=validateCareer(j.data.career||{});if(typeof j.data.domain==='string')out.domain=j.data.domain.slice(0,253);return out}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;switch(el.dataset.action){case'career-edit':careerModal();break;case'load-map':loadRouteMap(id);break;case'listing-notes':listingModal(id);showNotes('property:'+id);break;case'community-notes':communityModal(id);showNotes('community:'+id);break;case'listing':listingModal(id);break;case'community':communityModal(id);break;case'asset':assetModal(id);break;case'tele':assetModal(id,true);break;case'close':closeModal();break;case'route':selectedRoute=id;if(location.hash==='#routes'){view='routes';render()}else location.hash='routes';break;case'select-route':selectedRoute=id;render();break;case'copy-script':copy(D.assets.find(a=>a.id===id).script);break;case'copy-caption':copy(D.assets.find(a=>a.id===id).caption);break;case'export':exportProgress();break;case'import':$('#import-file').click();break;case'print':window.print();break;case'clear-filters':filters={query:'',island:'all',format:'all',stage:'all',page:1};render();break;case'page':filters.page+=Number(el.dataset.dir);render();$('#main').scrollIntoView({behavior:'smooth'});break;case'tele-play':if(teleTimer){clearInterval(teleTimer);teleTimer=null;el.textContent='Resume scrolling'}else{el.textContent='Pause';teleTimer=setInterval(()=>{const t=$('#tele-text');if(!t)return;const speed=Number($('#tele-speed').value);t.scrollTop+=speed/20;if(t.scrollTop+t.clientHeight>=t.scrollHeight-1){clearInterval(teleTimer);teleTimer=null;el.textContent='Start scrolling'}},50)}break;case'tele-reset':$('#tele-text').scrollTop=0;break}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.workspaceNote){updateNoteFeedback(el,writeNote(el.dataset.workspaceNote,el.value));return}if(el.id==='search'){const pos=el.selectionStart;filters.query=el.value;filters.page=1;$('#main').innerHTML=({listings,communities,scripts}[view])();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(el.dataset.assetNotes)setAsset(el.dataset.assetNotes,'notes',el.value);if(el.dataset.propertyNotes){state.properties[el.dataset.propertyNotes]={...prop(el.dataset.propertyNotes),notes:el.value};save()}if(el.id==='domain-note'){state.domain=el.value;save()}if(el.id==='tele-size')$('#tele-text').style.fontSize=el.value+'px'});
document.addEventListener('change',e=>{const el=e.target;if(['island-filter','format-filter','stage-filter'].includes(el.id)){filters[el.id.split('-')[0]]=el.value;filters.page=1;render()}if(el.dataset.status){setAsset(el.dataset.status,'status',el.value);toast('Production status saved.')}if(el.dataset.shot){const id=el.dataset.shot;setAsset(id,'shots',{...as(id).shots,[el.dataset.key]:el.checked})}if(el.dataset.propertyCheck){const id=el.dataset.propertyCheck;state.properties[id]={...prop(id),[el.dataset.key]:el.checked};save()}if(el.id==='route-date'){state.routeDates[el.dataset.route]=el.value;save();toast('Planning date saved.')}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>12000000)throw Error('Backup is too large. Choose a dashboard JSON export under 12 MB.');const next=validImport(JSON.parse(await f.text()));if(confirm('Replace this browser’s saved production progress with this backup? Export your current progress first if you need to keep it.')){state=next;save();render();toast('Progress backup imported.')}}catch(err){toast(err.message||'Could not import this file.')}e.target.value=''});
$('#backup-top').onclick=exportProgress;$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});document.addEventListener('keydown',e=>{if($('#modal').hidden)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const fs=[...$('#modal').querySelectorAll('button,a,input,select,textarea,[tabindex]')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=fs[0],last=fs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',navigate);
try{D=window.PRODUCTION_DATA;if(!D?.listings)throw Error('Production data missing');navigate()}catch(e){$('#main').innerHTML='<div class="empty"><h2>The studio could not load.</h2><p class="muted">Open this dashboard through its hosted URL or a local web server, then reload.</p><button class="button" onclick="location.reload()">Reload</button></div>';console.error(e)}
